/**  Todo el monitor. */
"full" | 
/**  Mitad izquierda. */
"left" | 
/**  Mitad derecha. */
"right" | 
/**  Mitad de arriba. */
"top" | 
/**  Mitad de abajo. */
"bottom" | 
/**  El centro (la mitad del ancho y del alto). */
"center" | 
/**  Rectángulo dibujado a mano. */
"custom";
